<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Project Name Generator','description'=>'Generate memorable names for projects and ideas.','url'=>'https://smarttoolz.in/tools/project-name-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Project Name Generator</h1><p>Generate random two-word project names.</p></section><section class="tool-workspace"><div class="tool-panel"><button id="go" class="tool-btn">Generate Names</button><textarea id="o" rows="10" readonly></textarea></div></section></main><script>let a=['Nova','Pixel','Bright','Swift','Cloud','Blue','Smart','Fresh','Rapid','Prime'],b=['Labs','Works','Tools','Hub','Forge','Box','Studio','Flow','Nest','Craft'];go.onclick=()=>o.value=Array.from({length:10},()=>a[Math.random()*a.length|0]+' '+b[Math.random()*b.length|0]).join('\n');go.click()</script><?php smarttoolz_tool_page_end(); ?>